import type L from 'leaflet'
import type { AnyProps, ClusterFeature, PointFeature } from 'supercluster'
import type { ReactNode } from 'react'
import type { GeoJsonObject } from 'geojson'
import type { ArenaAnyNodeDef, ArenaPoint } from '@openforis/arena-core'

// properties of every map layer point: the key identifies the point in its layer
export type MapPointProperties = {
  key: string
}

// GeoJSON point feature of a map layer
export type MapPointFeature<P extends MapPointProperties = MapPointProperties> = PointFeature<P>

// cluster of points, generated by supercluster
export type MapClusterFeature = ClusterFeature<AnyProps>

export type MapClusterOrPointFeature<P extends MapPointProperties = MapPointProperties> =
  MapClusterFeature | MapPointFeature<P>

/**
 * Tells clusters from points: supercluster sets `cluster: true` in the properties of a cluster.
 * @param {MapClusterOrPointFeature} feature - The feature returned by supercluster.
 * @returns {boolean} True if the feature is a cluster.
 */
export const isMapClusterFeature = <P extends MapPointProperties>(
  feature: MapClusterOrPointFeature<P>
): feature is MapClusterFeature => Boolean((feature.properties as { cluster?: boolean }).cluster)

export type ClusterIconCreator = (params: { count: number; size: number; color: string }) => L.DivIcon

// point of a coordinate or geo attribute value
export type GeoAttributePointProperties = MapPointProperties & {
  ancestorsKeys: string[]
  center: boolean
  parentUuid: string
  point: ArenaPoint
  recordOwnerUuid: string
  recordUuid: string
  // GeoJSON value of a geo attribute
  data?: GeoJsonObject
}

export type GeoAttributePointFeature = MapPointFeature<GeoAttributePointProperties>

// point of a sampling point data item
export type SamplingPointProperties = MapPointProperties & {
  ancestorsKeys: string[]
  cluster: false
  itemCodes: string[]
  itemLatLongPoint: ArenaPoint
  itemUuid: string
  location: string
  locationPoint: ArenaPoint | null
  recordUuid?: string
}

export type SamplingPointFeature = MapPointFeature<SamplingPointProperties>

// opens the record editor at the record (and entity) of a point; null closes it
export type RecordEditClickHandler = (params: { recordUuid: string; parentUuid?: string } | null) => void

// marker of a point: a circle marker, or the GeoJSON layer of a geo attribute value
export type MapPointMarker = L.CircleMarker | L.GeoJSON

// keeps the markers rendered by key, to open the popup of a point
export type SetMarkerByKey = (params: { key: string; marker: MapPointMarker | null }) => void

// creates a record from a sampling point data item; the callback receives the new record
export type CreateRecordFromSamplingPointDataItem = (params: {
  itemUuid: string
  callback?: (params: { recordUuid: string }) => void
}) => Promise<void>

// called with the points of a geo attribute layer on every data fetch, before filtering
export type GeoAttributePointsLoadedHandler = (params: { layerKey: string; points: GeoAttributePointFeature[] }) => void

export type GeoAttributePointsFilter = (point: GeoAttributePointFeature) => boolean

// renders the popup of a geo attribute point, instead of the default one
export type GeoAttributePopupRenderer = (params: {
  attributeDef: ArenaAnyNodeDef
  pointFeature: GeoAttributePointFeature
  flyToNextPoint?: (point: GeoAttributePointFeature) => void
  flyToPreviousPoint?: (point: GeoAttributePointFeature) => void
}) => ReactNode
